import{c as s,Q as a,j as i,m as t}from"./chunks/framework.BPKcPtvA.js";const k=JSON.parse('{"title":"Cross-domain ForwardAuth","description":"How GateKeeper authenticates users across apps on different domains or TLDs.","frontmatter":{"title":"Cross-domain ForwardAuth","description":"How GateKeeper authenticates users across apps on different domains or TLDs."},"headers":[],"relativePath":"src/content/docs/integrations/cross-domain.md","filePath":"src/content/docs/integrations/cross-domain.md"}'),o={name:"src/content/docs/integrations/cross-domain.md"};function n(r,e,d,h,p,l){return a(),i("div",null,[...e[0]||(e[0]=[t(`<p>The standard Traefik ForwardAuth setup works seamlessly when all your apps share a common parent domain (for example <code>app.example.com</code> and <code>other.example.com</code> can both receive a cookie set on <code>.example.com</code>). When apps live on <strong>completely different domains</strong> (for example <code>app.example.com</code> and <code>app.otherdomain.io</code>), cookies set by GateKeeper cannot be shared across domains - this is a browser security constraint.</p><p>GateKeeper solves this with a cross-domain token handoff.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>A user visits <code>app.otherdomain.io</code>. Traefik sends the verify request to GateKeeper.</li><li>GateKeeper sees there is no valid session for this host and redirects to <code>/login?redirect_uri=https://app.otherdomain.io/the-page</code>.</li><li>The user logs in on <code>auth.example.com</code>. After authentication, GateKeeper detects that the redirect target is outside the shared cookie domain.</li><li>Instead of redirecting directly, GateKeeper generates a <strong>cross-domain token</strong> - a short-lived (5-minute), HMAC-SHA256 signed token containing the session ID.</li><li>The browser is sent to <code>https://app.otherdomain.io/_gk/auth?token=XXX&amp;redirect=/the-page</code>.</li><li>Traefik intercepts this request and forwards it to GateKeeper&#39;s verify endpoint.</li><li>GateKeeper validates the HMAC signature and expiry, extracts the session ID, and sets a <code>gk_session</code> cookie scoped to <code>app.otherdomain.io</code> (no <code>Domain</code> attribute, so the browser scopes it to the exact host).</li><li>GateKeeper redirects back to <code>/the-page</code>. The user is now authenticated on <code>app.otherdomain.io</code> and future requests carry the host-scoped session cookie.</li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>No extra configuration is needed if you set <code>COOKIE_DOMAIN</code>. GateKeeper automatically detects when a redirect target is outside the shared domain and triggers the cross-domain handoff.</p><p>If <code>COOKIE_DOMAIN</code> is not set, all apps are treated as same-domain and the cross-domain flow is never used.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">COOKIE_DOMAIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # covers *.example.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://auth.example.com</span></span></code></pre></div><h2 id="token-security" tabindex="-1">Token security <a class="header-anchor" href="#token-security" aria-label="Permalink to &quot;Token security&quot;">​</a></h2><p>Cross-domain tokens are signed with HMAC-SHA256 using <code>SECRET_KEY</code>. Properties:</p><ul><li><strong>Short-lived</strong> - tokens expire after 5 minutes.</li><li><strong>Single use</strong> - the token contains the session ID but is consumed when the cookie is set.</li><li><strong>Not replayable</strong> - a token captured in transit cannot be replayed after expiry, and it is tied to the specific session.</li><li><strong>Transmitted in the URL</strong> - the token appears in the query string and may appear in server logs. The short expiry limits the window an intercepted token is useful.</li></ul><h2 id="traefik-configuration" tabindex="-1">Traefik configuration <a class="header-anchor" href="#traefik-configuration" aria-label="Permalink to &quot;Traefik configuration&quot;">​</a></h2><p>The <code>/_gk/auth</code> path on each protected app&#39;s domain must be reachable by Traefik&#39;s ForwardAuth check. No special configuration is needed - the standard <code>gk-auth</code> middleware handles this path automatically.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">http</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  middlewares</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    gk-auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      forwardAuth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://auth.example.com/auth/verify&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        authResponseHeaders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-Auth-User</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-Auth-Email</span></span></code></pre></div><p>Apply this middleware to routes on any domain, including domains unrelated to <code>example.com</code>. GateKeeper handles the cross-domain handoff transparently.</p>`,15)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
